const teamSheet=document.createElement('div');teamSheet.className='tn22-team-sheet';teamSheet.innerHTML=`<div class="tn22-team-panel"><div class="tn22-handle"></div><h3>Команда STLuxe</h3><div class="tn22-team-list">${MASTERS.map(m=>`<button class="tn22-team-row" type="button" data-sheet-mid="${m.id}"><span class="tn22-team-mini">${m.initial}</span><span><strong>${m.name}</strong><span>${m.role} · ${m.detail}</span></span><b>→</b></button>`).join('')}</div></div>`;root.appendChild(teamSheet);team.querySelector('.tn22-team-all').onclick=()=>{teamSheet.classList.add('open');document.body.style.overflow='hidden'};teamSheet.onclick=e=>{if(e.target===teamSheet){teamSheet.classList.remove('open');document.body.style.overflow=''}};

